// Star catalogue, constellation figures and asterisms (generated by scripts/build-catalog.ts).
import raw from './data/catalog.json';
import { eqjUnit } from './astro';

export interface Catalog {
  nStars: number;
  /** Unit vectors, J2000 equatorial, 3 per star. */
  starVec: Float64Array;
  mag: Float32Array;
  bv: Float32Array;
  hip: Int32Array;
  des: string[];
  con: string[];
  /** star index -> proper name */
  names: Map<number, string>;
  /** Constellation figure vertices: unit vectors + magnitude of the star at each vertex. */
  lineVec: Float64Array;
  lineMag: Float32Array;
  /** Segments as pairs of vertex indices, flat [a0,b0,a1,b1,...]. */
  lineSeg: Int32Array;
  asterisms: Array<{ name: string; paths: number[][] }>;
  constellations: Array<{ id: string; name: string; rank: number; vec: [number, number, number] }>;
  conName: Map<string, string>;
}

function build(): Catalog {
  const stars = raw.stars as number[][];
  const n = stars.length;
  const starVec = new Float64Array(n * 3);
  const mag = new Float32Array(n);
  const bv = new Float32Array(n);
  stars.forEach((s, i) => {
    const v = eqjUnit(s[0], s[1]);
    starVec[i * 3] = v[0]; starVec[i * 3 + 1] = v[1]; starVec[i * 3 + 2] = v[2];
    mag[i] = s[2]; bv[i] = s[3];
  });

  const lv: number[] = [], lm: number[] = [], seg: number[] = [];
  for (const c of raw.lines as Array<{ paths: number[][][] }>) {
    for (const path of c.paths) {
      let prev = -1;
      for (const [ra, dec, m] of path) {
        const v = eqjUnit(ra, dec);
        const idx = lm.length;
        lv.push(v[0], v[1], v[2]); lm.push(m);
        if (prev >= 0) seg.push(prev, idx);
        prev = idx;
      }
    }
  }

  const constellations = (raw.constellations as Array<{ id: string; name: string; rank: number; ra: number; dec: number }>)
    .map(c => ({ id: c.id, name: c.name, rank: c.rank, vec: eqjUnit(c.ra, c.dec) }));

  return {
    nStars: n,
    starVec, mag, bv,
    hip: Int32Array.from(raw.hip as number[]),
    des: raw.des as string[],
    con: raw.con as string[],
    names: new Map((raw.names as Array<[number, string]>).map(([i, nm]) => [i, nm])),
    lineVec: Float64Array.from(lv),
    lineMag: Float32Array.from(lm),
    lineSeg: Int32Array.from(seg),
    asterisms: raw.asterisms as Catalog['asterisms'],
    constellations,
    conName: new Map(constellations.map(c => [c.id, c.name])),
  };
}

export const catalog: Catalog = build();
